import math

def respond(image, text, model, risk_head, ask_threshold):
    probs = model.next_token_probs(image, text)        # read the PAIR, never one input
    entropy = -sum(p * math.log(p) for p in probs if p > 0)
    risk = risk_head(image, text)                       # learned cross-modal risk score
    signal = combine(entropy, risk)                     # risk-conditioned uncertainty
    if signal > ask_threshold:
        return ask_clarifying_question(image, text)     # settle the intent before acting
    return model.generate(image, text)
